<script setup lang="ts">
import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api,describe} from '../api';import type {TaskPage} from '../types'
const project=String(useRoute().params.projectId), page=ref(1),size=20,assignee=ref(''),priority=ref(''),completed=ref(''), result=ref<TaskPage|null>(null),error=ref(''),busy=ref(false)
async function load(reset=false){if(reset)page.value=1;busy.value=true;error.value='';try{const q=new URLSearchParams({page:String(page.value),size:String(size)});if(assignee.value)q.set('assigneeName',assignee.value);if(priority.value)q.set('priority',priority.value);if(completed.value)q.set('completed',completed.value);result.value=await api<TaskPage>(`/api/projects/${project}/tasks?${q}`)}catch(e){error.value=describe(e)}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><div class="page-head"><div><p class="eyebrow">项目 {{project}} / 正式任务</p><h1>任务列表</h1><p class="muted">会议中确认的行动，在这里继续推进。</p></div><router-link class="button secondary" :to="`/projects/${project}/import`">+ 导入会议</router-link></div><form class="card filters" @submit.prevent="load(true)"><label>负责人<input v-model.trim="assignee" placeholder="筛选负责人"></label><label>优先级<select v-model="priority"><option value="">全部</option><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option></select></label><label>完成状态<select v-model="completed"><option value="">全部</option><option value="false">未完成</option><option value="true">已完成</option></select></label><button class="primary">筛选</button></form><p v-if="error" class="error">{{error}}</p><p v-if="busy" class="muted">正在加载任务…</p><template v-else-if="result"><div class="row"><h2>全部任务</h2><span class="muted">共 {{result.total}} 项</span></div><p v-if="!result.records.length" class="card muted">没有符合条件的任务。</p><div v-for="task in result.records" :key="task.id" class="card task"><div><div class="row"><h3>{{task.title}}</h3><span class="badge" :class="task.priority?.toLowerCase()">{{task.priority || '未设置'}}</span></div><p class="muted">负责人：{{task.assigneeName || '待定'}} <span class="divider">·</span> 截止：{{task.deadline || '未设置'}}</p></div><span class="badge">{{task.isCompleted ? '已完成' : '进行中'}}</span></div><div class="pagination"><button class="secondary" :disabled="page<=1" @click="page--;load()">上一页</button><span>第 {{page}} 页</span><button class="secondary" :disabled="page*size>=result.total" @click="page++;load()">下一页</button></div></template></template>
